"""Exploration: which conditions on the naive count iterates hold exactly?"""
from fractions import Fraction as Q
import itertools, random, sys, time

from spiral_ln.evaluation_feedback_multigen import (
    drift_kernel, drift_levels, gate_threshold, kernel_iterates, naive_threshold,
    NONUNIFORM_LATTICES)

FIXED = {1: Q(1)}


def landing_law(kernel, items, top):
    """pi_{i+1}(J) for every level i from the naive kernel rows at count 0."""
    pi = {}
    for i in range(top + 1):
        row = {}
        for (J, _), prob in kernel[(0, i)][1:]:
            row[J] = prob
        row[0] = kernel[(0, i)][0][1]  # F(0)^K = P(M = 0)
        pi[i] = row
    return pi


def explore(items, candidates, levels, H, name):
    top = len(levels) - 1
    up = lambda i: min(top, i + 1)
    kernel = drift_kernel(items, candidates, levels, FIXED, naive_threshold(items))
    states = list(kernel)
    pi = landing_law(kernel, items, top)
    out = {"name": name}
    # count iterates
    u = kernel_iterates(kernel, lambda x: Q(x[0]), H)
    # pointwise cone u_k(J,i+1) >= u_k(c,i), J > c
    worst = None
    for k in range(H + 1):
        for (c, i) in states:
            for J in range(c + 1, items + 1):
                d = u[k][(J, up(i))] - u[k][(c, i)]
                if d < 0 and (worst is None or d < worst[0]):
                    worst = (d, k, (c, i), J)
    out["count_pointwise_cone_worst"] = worst
    # prefix-window cone
    worst = None
    first = None
    for k in range(H + 1):
        for (c, i) in states:
            run = Q(0)
            for J in range(c + 1, items + 1):
                run += pi[i].get(J, Q(0)) * (u[k][(J, up(i))] - u[k][(c, i)])
                if run < 0:
                    if worst is None or run < worst[0]:
                        worst = (run, k, (c, i), J)
                    if first is None:
                        first = (run, k, (c, i), J)
    out["count_prefix_cone_worst"] = worst
    out["count_prefix_cone_first"] = first
    # unit-window cone: u_k(c+1,i+1) >= u_k(c,i)
    worst = None
    for k in range(H + 1):
        for (c, i) in states:
            if c < items:
                d = u[k][(c + 1, up(i))] - u[k][(c, i)]
                if d < 0 and (worst is None or d < worst[0]):
                    worst = (d, k, (c, i))
    out["count_unit_cone_worst"] = worst
    # hitting indicators
    hit = {}
    for m in range(1, items + 1):
        f = lambda x, m=m: Q(int(x[0] >= m))
        um = kernel_iterates(kernel, f, H)
        res = {}
        # M1 below m: u(c,i) >= u(c+1,i) for c+1 < m
        w1 = None
        for k in range(H + 1):
            for (c, i) in states:
                if c + 1 < m:
                    d = um[k][(c, i)] - um[k][(c + 1, i)]
                    if d < 0 and (w1 is None or d < w1[0]):
                        w1 = (d, k, (c, i))
        res["M1_below_m"] = w1
        w2 = None
        for k in range(H + 1):
            for (c, i) in states:
                if i < top and c < m:
                    d = um[k][(c, i + 1)] - um[k][(c, i)]
                    if d < 0 and (w2 is None or d < w2[0]):
                        w2 = (d, k, (c, i))
        res["M2"] = w2
        # NBU: s_k(x) <= (1-h(x)) s_{k-1}(x), s = 1-u, 1-h = F_{i+1}(m-1)^K = sum_{J<m} pi(J)
        wn = None
        for k in range(1, H + 1):
            for (c, i) in states:
                if c < m:
                    surv1 = sum(pi[i].get(J, Q(0)) for J in range(0, m))
                    d = surv1 * (1 - um[k - 1][(c, i)]) - (1 - um[k][(c, i)])
                    if d < 0 and (wn is None or d < wn[0]):
                        wn = (d, k, (c, i))
        res["NBU"] = wn
        # pointwise cone for indicator
        wc = None
        for k in range(H + 1):
            for (c, i) in states:
                for J in range(c + 1, items + 1):
                    d = um[k][(J, up(i))] - um[k][(c, i)]
                    if d < 0 and (wc is None or d < wc[0]):
                        wc = (d, k, (c, i), J)
        res["pointwise_cone"] = wc
        wp = None
        for k in range(H + 1):
            for (c, i) in states:
                run = Q(0)
                for J in range(c + 1, items + 1):
                    run += pi[i].get(J, Q(0)) * (um[k][(J, up(i))] - um[k][(c, i)])
                    if run < 0 and (wp is None or run < wp[0]):
                        wp = (run, k, (c, i), J)
        res["prefix_cone"] = wp
        hit[m] = res
    out["hitting"] = hit
    return out


def fmt(v):
    if v is None:
        return "ok"
    return "FAIL " + str(tuple((float(x) if isinstance(x, Q) else x) for x in v))


def main():
    random.seed(1)
    H = 12
    lattices = {
        "std8": drift_levels(Q(1, 4), Q(1, 8)),
        "std16": drift_levels(Q(1, 4), Q(1, 16)),
        "nu0": NONUNIFORM_LATTICES[0],
        "nu1": NONUNIFORM_LATTICES[1],
        "jump_half_one": (Q(1, 2), Q(1, 2), Q(1)),
        "jump_quarter_one": (Q(1, 4), Q(1, 4), Q(1, 4), Q(1)),
        "low_then_one": (Q(1, 8), Q(1, 8), Q(1)),
        "zero_half_one": (Q(0), Q(1, 2), Q(1)),
        "half_half_half_one": (Q(1, 2), Q(1, 2), Q(1, 2), Q(1)),
        "tiny_then_big": (Q(1, 16), Q(1, 16), Q(15, 16), Q(1)),
        "mid_mid_one": (Q(1, 2), Q(3, 4), Q(1)),
    }
    for r in range(4):
        vals = sorted(Q(random.randint(0, 16), 16) for _ in range(random.randint(2, 5)))
        lattices[f"rand{r}"] = tuple(vals)
    cells = [(3, 1), (4, 1), (4, 2), (5, 1), (6, 2), (8, 2)]
    t0 = time.time()
    for items, candidates in cells:
        for lname, levels in lattices.items():
            name = f"n={items},K={candidates},lat={lname}"
            res = explore(items, candidates, levels, H, name)
            print(name)
            print("  count pointwise cone:", fmt(res["count_pointwise_cone_worst"]))
            print("  count unit cone     :", fmt(res["count_unit_cone_worst"]))
            print("  count prefix cone   :", fmt(res["count_prefix_cone_worst"]))
            if res["count_prefix_cone_first"]:
                print("  count prefix first  :", fmt(res["count_prefix_cone_first"]))
            bad = {}
            for m, r in res["hitting"].items():
                for key, v in r.items():
                    if v is not None:
                        bad.setdefault(key, []).append((m, fmt(v)))
            for key, v in bad.items():
                print(f"  hit {key}: ", v[:3])
            sys.stdout.flush()
    print("elapsed", time.time() - t0)


if __name__ == "__main__":
    main()

