"""Proof-step inequalities, two-point law cone, K=4, and the R1 same-uniform crossing witness."""
from fractions import Fraction as Q
from collections import deque
import random, sys, time

from spiral_ln.evaluation_feedback_multigen import (
    drift_kernel, drift_levels, gate_threshold, kernel_iterates, naive_threshold,
    binomial_cdf, NONUNIFORM_LATTICES, NONGATE_THRESHOLDS, DRIFT_GAINS)
from spiral_ln.evaluation_game_feedback import _binomial_pmf

FIXED = {1: Q(1)}


def pi_from_kernel(kernel, items, top):
    pi = {}
    for i in range(top + 1):
        row = {0: kernel[(0, i)][0][1]}
        for (J, _), prob in kernel[(0, i)][1:]:
            row[J] = prob
        pi[i] = row
    return pi


def proof_steps(items, candidates, levels, H):
    """Check the intermediate inequalities of the hitting lemmas exactly."""
    top = len(levels) - 1
    up = lambda i: min(top, i + 1)
    kernel = drift_kernel(items, candidates, levels, FIXED, naive_threshold(items))
    states = list(kernel)
    pi = pi_from_kernel(kernel, items, top)
    ok = {"nbu": True, "nbu_step_e": True, "L3_step_R": True, "L3_step_e": True, "L2": True, "L3": True,
          "window": True, "window_count": True}
    for m in range(1, items + 1):
        um = kernel_iterates(kernel, lambda x, m=m: Q(int(x[0] >= m)), H)
        s = [{x: 1 - um[k][x] for x in states} for k in range(H + 1)]
        surv1 = {i: sum(pi[i].get(J, Q(0)) for J in range(m)) for i in range(top + 1)}  # 1 - H(i)
        for (c, i) in states:
            if c >= m:
                continue
            land = {J: pi[i][J] for J in range(c + 1, m) if pi[i].get(J, Q(0))}
            B = sum(land.values(), Q(0))
            A = pi[i].get(0, Q(0)) if c == 0 else sum(pi[i].get(J, Q(0)) for J in range(c + 1))
            # NBU
            for k in range(1, H + 1):
                ok["nbu"] &= s[k][(c, i)] <= surv1[i] * s[k - 1][(c, i)]
            if B:
                e = [sum(p * s[k][(J, up(i))] for J, p in land.items()) / B for k in range(H + 1)]
                for k in range(1, H + 1):
                    ok["nbu_step_e"] &= e[k] <= surv1[up(i)] * e[k - 1]
                    ok["nbu"] &= e[k] <= s[k][(c, i)]
            # L2: s(c,i) <= s(c+1,i) for c+1<m ; L3: s(c,i+1) <= s(c,i)
            for k in range(H + 1):
                if c + 1 < m:
                    ok["L2"] &= s[k][(c, i)] <= s[k][(c + 1, i)]
                if i < top:
                    ok["L3"] &= s[k][(c, i + 1)] <= s[k][(c, i)]
            # L3 proof steps: e1_r >= sigma_r, and R_k >= sigma_k
            if i < top:
                sigma = [s[k][(c, i + 1)] for k in range(H + 1)]
                if B:
                    for r in range(H + 1):
                        ok["L3_step_e"] &= e[r] >= sigma[r]
                R = [Q(1)]
                for k in range(1, H + 1):
                    R.append(A * R[-1] + B * sigma[k - 1])
                    ok["L3_step_R"] &= R[k] >= sigma[k]
            # window
            for k in range(H + 1):
                run = Q(0)
                for J in range(c + 1, items + 1):
                    run += pi[i].get(J, Q(0)) * (um[k][(J, up(i))] - um[k][(c, i)])
                    ok["window"] &= run >= 0
    u = kernel_iterates(kernel, lambda x: Q(x[0]), H)
    for k in range(H + 1):
        for (c, i) in states:
            run = Q(0)
            for J in range(c + 1, items + 1):
                run += pi[i].get(J, Q(0)) * (u[k][(J, up(i))] - u[k][(c, i)])
                ok["window_count"] &= run >= 0
    return ok


def window_two_point(items, candidates, levels, H, law):
    """Prefix-window condition for the count under a mixed gain law: Q_t u_k <= P u_k for all t."""
    top = len(levels) - 1
    kernel = drift_kernel(items, candidates, levels, law, naive_threshold(items))
    states = list(kernel)
    u = kernel_iterates(kernel, lambda x: Q(x[0]), H)
    worst = None
    for k in range(H + 1):
        for (c, i) in states:
            entries = kernel[(c, i)][1:]
            # group by landing count J, in increasing J
            byJ = {}
            for (J, i2), prob in entries:
                byJ.setdefault(J, []).append(((J, i2), prob))
            run = Q(0)
            for J in sorted(byJ):
                for y, prob in byJ[J]:
                    run += prob * (u[k][y] - u[k][(c, i)])
                if run < 0 and (worst is None or run < worst[0]):
                    worst = (run, k, (c, i), J)
    return worst


def crossing_witness(items, levels, threshold, m, horizon):
    """BFS over joint (naive, gated) states under the same-uniform quantile coupling, K=1.
    Find a path with gated level > naive level while naive count < m."""
    top = len(levels) - 1
    cdf = [binomial_cdf(items, p) for p in levels]
    def interval(l, j):
        lo = cdf[l][j - 1] if j else Q(0)
        return lo, cdf[l][j]
    start_states = [(c, i, c, i) for i in range(top + 1) for c in range(m)]
    parent = {s: None for s in start_states}
    queue = deque(start_states)
    depth = {s: 0 for s in start_states}
    while queue:
        st = queue.popleft()
        c0, i0, ct, it = st
        if it > i0 and c0 < m:
            # reconstruct
            path = []
            cur = st
            while parent[cur] is not None:
                prev, u, j0, jt = parent[cur]
                path.append((u, j0, jt, cur))
                cur = prev
            path.reverse()
            return {"start": cur, "path": path, "end": st}
        if depth[st] >= horizon:
            continue
        l0, lt = min(top, i0 + 1), min(top, it + 1)
        for j0 in range(items + 1):
            a0, b0 = interval(l0, j0)
            if b0 <= a0:
                continue
            for jt in range(items + 1):
                at, bt = interval(lt, jt)
                lo, hi = max(a0, at), min(b0, bt)
                if hi <= lo:
                    continue
                u = (lo + hi) / 2
