    states = list(kernel)
    pi = pi_from_kernel(kernel, items, top)
    ok = {"nbu": True, "nbu_step_e": True, "L3_step_R": True, "L3_step_e": True, "L2": True, "L3": True,
          "window": True, "window_count": True}
    for m in range(1, items + 1):
        um = kernel_iterates(kernel, lambda x, m=m: Q(int(x[0] >= m)), H)
        s = [{x: 1 - um[k][x] for x in states} for k in range(H + 1)]
        surv1 = {i: sum(pi[i].get(J, Q(0)) for J in range(m)) for i in range(top + 1)}  # 1 - H(i)
        for (c, i) in states:
            if c >= m:
                continue
            land = {J: pi[i][J] for J in range(c + 1, m) if pi[i].get(J, Q(0))}
            B = sum(land.values(), Q(0))
            A = pi[i].get(0, Q(0)) if c == 0 else sum(pi[i].get(J, Q(0)) for J in range(c + 1))
            # NBU
            for k in range(1, H + 1):
                ok["nbu"] &= s[k][(c, i)] <= surv1[i] * s[k - 1][(c, i)]
            if B:
                e = [sum(p * s[k][(J, up(i))] for J, p in land.items()) / B for k in range(H + 1)]
                for k in range(1, H + 1):
                    ok["nbu_step_e"] &= e[k] <= surv1[up(i)] * e[k - 1]
                    ok["nbu"] &= e[k] <= s[k][(c, i)]
